<script setup>
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import SectionTitle from '../components/SectionTitle.vue'
import MetricCard from '../components/MetricCard.vue'
import TaskStatus from '../components/TaskStatus.vue'
import RemindersPanel from '../components/RemindersPanel.vue'
import { isDateReminder, reminderDraft, reminderPayload, reminderSuggestions } from '../services/reminders'
import { api } from '../services/api'
import { workspace as s } from '../services/workspace'
import { formatDate, formatKm, today, alertThresholdKm, alertProgress, alertTypes } from '../services/format'
import { useTask } from '../composables/useTask'
const {busy,error,notice,run}=useTask(), rows=ref([]), form=ref(null), editId=ref(null), showCompleted=ref(false)
const route=useRoute(), formElement=ref(null), formHeading=ref(null), loadFailed=ref(false)
const path='/motocicletas/'+s.motoId+'/alertas', moto=computed(()=>s.motos.find(m=>m.id===Number(s.motoId))), visible=computed(()=>rows.value.filter(r=>showCompleted.value||r.status!=='concluido'))
const due=r=>(r.km_limite>0&&moto.value?.km_atual>=alertThresholdKm(r))||(r.data_limite&&r.data_limite<=today())
async function load(){try{rows.value=(await api.get(path)).data;loadFailed.value=false}catch(e){loadFailed.value=true;throw e}}
function scrollTo(element){if(!element)return;element.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});element.focus({preventScroll:true})}
function open(r=null,type='troca_oleo'){editId.value=r?.id||null;form.value=r?{...r}:reminderDraft(type,moto.value?.km_atual||0);nextTick(()=>{formElement.value?.scrollIntoView({block:'start',behavior:'auto'});formHeading.value?.focus({preventScroll:true})})}
function configure(type){if(!reminderSuggestions.some(item=>item.type===type))return;const existing=rows.value.find(row=>row.tipo_alerta===type&&row.status!=='concluido');if(existing){if(existing.status==='pendente')open(existing);else{notice.value='Este lembrete já está configurado. Conclua-o antes de programar o próximo vencimento.';nextTick(()=>scrollTo(document.getElementById('lembrete-'+existing.id)))}return}open(null,type)}
async function save(){await run(async()=>{const body=reminderPayload(form.value);if(editId.value)await api.put(path+'/'+editId.value,body);else await api.post(path,body);form.value=null;await load()},'Alerta salvo.')}
async function complete(r){await run(async()=>{await api.put(path+'/'+r.id,{status:'concluido'});await load()},'Alerta concluído. Cadastre o próximo limite quando desejar.')}
async function remove(r){if(!window.confirm('Excluir este alerta?'))return;await run(async()=>{await api.delete(path+'/'+r.id);await load()},'Alerta excluído.')}
function suggestChainCycle(){if(isDateReminder(form.value.tipo_alerta)){form.value.km_limite='';form.value.km_base='';return}if(form.value.km_base==='')form.value.km_base=moto.value?.km_atual||0;if(form.value.tipo_alerta==='lubrificacao_corrente'&&!form.value.km_limite){form.value.km_base=moto.value?.km_atual||0;const next=Number(form.value.km_base)+500;if(next<=4294967295)form.value.km_limite=next}}
watch(()=>route.query.configurar,type=>{if(!busy.value&&s.motoId)configure(type)})
onMounted(async()=>{if(s.motoId){await run(load);if(!loadFailed.value){if(route.query.configurar)configure(route.query.configurar);else if(/^#lembrete-\d+$/.test(route.hash))nextTick(()=>scrollTo(document.getElementById(route.hash.slice(1))))}}})
</script>
<template><div class="page-stack"><SectionTitle>Alertas e Lembretes</SectionTitle><TaskStatus :busy="busy" :error="error" :notice="notice"/><p v-if="!s.motoId">Cadastre uma moto na Garagem para configurar alertas.</p><template v-else><div class="metrics-grid metrics-three"><MetricCard icon="⚠️" label="Ativos" :value="rows.filter(r=>r.status!=='concluido').length" accent/><MetricCard icon="🔔" label="Atenção" :value="rows.filter(r=>r.status!=='concluido'&&due(r)).length"/><MetricCard icon="🏍" label="Odômetro atual" :value="formatKm(moto?.km_atual||0)+' km'"/></div><div class="toolbar"><button class="button button-lime" :disabled="busy" @click="open()">+ Novo alerta</button><button class="button button-ghost" :disabled="busy" @click="run(load)">Atualizar</button><label><input v-model="showCompleted" type="checkbox"/> Mostrar concluídos</label></div><RemindersPanel v-if="!form" :alerts="rows" :current-km="Number(moto?.km_atual||0)" :loading="busy" :unavailable="loadFailed" suggestions-only @configure="configure"/><form v-if="form" ref="formElement" class="demo-form reminder-edit-form" @submit.prevent="save"><h3 ref="formHeading" tabindex="-1">{{editId?'Editar':'Novo'}} alerta</h3><fieldset :disabled="busy"><div class="form-grid"><label class="field">Serviço<select v-model="form.tipo_alerta" @change="suggestChainCycle"><option v-for="(name,key) in alertTypes" :key="key" :value="key">{{name}}</option></select></label><label v-if="!isDateReminder(form.tipo_alerta)" class="field">Limite absoluto do odômetro<input v-model="form.km_limite" type="number" inputmode="numeric" min="1" max="4294967295" :required="!form.data_limite"/></label><label v-if="form.km_limite && !isDateReminder(form.tipo_alerta)" class="field">KM de referência do último serviço<input v-model="form.km_base" type="number" inputmode="numeric" min="0" :max="Math.min(Number(form.km_limite)-1,Number(moto?.km_atual||0))" required/></label><label class="field">{{isDateReminder(form.tipo_alerta)?'Data de vencimento':'Data limite (o que vencer primeiro)'}}<input v-model="form.data_limite" type="date" :required="!form.km_limite"/></label></div><p v-if="isDateReminder(form.tipo_alerta)" class="field-hint">Informe o vencimento do documento ou da apólice. O aviso ocorre na data informada; concluir não registra pagamento nem cria o próximo vencimento automaticamente.</p><p v-else class="field-hint">Aviso ao percorrer 90% do intervalo entre o KM de referência e o próximo limite, ou na data informada. Para lubrificação da corrente, sugestão editável de 500 km; siga o manual e as condições de uso. Confira o KM do último serviço; o valor inicial é o odômetro atual.</p><div class="form-actions"><button class="button button-black">Salvar</button><button type="button" class="button button-ghost" @click="form=null">Cancelar</button></div></fieldset></form><div class="maintenance-alert-list"><article v-for="r in visible" :id="'lembrete-'+r.id" tabindex="-1" :key="r.id" class="panel maintenance-alert" :class="{'maintenance-alert-overdue':due(r)&&r.status!=='concluido'}"><div class="alert-card-heading"><h3>{{alertTypes[r.tipo_alerta] || r.tipo_alerta}}</h3><span class="status-badge" :class="due(r)&&r.status!=='concluido'?'status-red':'status-green'">{{r.status==='notificado'?'Notificado':r.status==='concluido'?'Concluído':due(r)?'Atenção':'Programado'}}</span></div><p v-if="r.km_limite">Limite: {{formatKm(r.km_limite)}} km · aviso a partir de {{formatKm(alertThresholdKm(r))}} km</p><p v-if="r.km_limite">Referência: {{formatKm(r.km_base||0)}} km · intervalo de {{formatKm(r.km_limite-(r.km_base||0))}} km</p><p v-if="r.data_limite">Data limite: {{formatDate(r.data_limite)}}</p><div v-if="r.km_limite" class="alert-progress" aria-hidden="true"><span :style="{width:alertProgress(r,moto.km_atual)+'%'}"></span></div><div class="form-actions"><button v-if="r.status==='pendente'" class="button button-ghost" :disabled="busy" @click="open(r)">Editar</button><button v-if="r.status!=='concluido'" class="button button-lime" :disabled="busy" @click="complete(r)">{{isDateReminder(r.tipo_alerta)||r.tipo_alerta==='abastecimento'?'Marcar como concluído':'Marcar serviço concluído'}}</button><button class="button button-danger" :disabled="busy" @click="remove(r)">Excluir</button></div></article><p v-if="!busy&&!visible.length">Nenhum alerta neste filtro.</p></div><p class="field-hint">Concluir um lembrete não cria outro automaticamente nem registra serviço, abastecimento ou pagamento. Use Manutenções ou Gastos para registrar o que foi realizado e programe o próximo vencimento. <RouterLink to="/configuracoes">Ative notificações em Configurações.</RouterLink></p></template></div></template>

<style scoped>
.reminder-edit-form,.maintenance-alert{scroll-margin-top:110px}
</style>
